"""Powerlift instance 00 driver. Usage: python /app/output/gen.py reset_reach|grip|lift|hold"""
import json, sys
import numpy as np
from PIL import Image
from rcb_client import Robot

CAM = "room_camera"
STATE = "/app/output/episode_targets.json"

def save_obs(res, tag):
    for name, frame in res.last.items():
        Image.fromarray(frame).save(f"/app/output/{tag}_{name}.png")

def report(res, spec, label):
    now = res.meta.get("proprio", {}).get("now", [])
    names = spec.get("proprio_layout", [])
    arm = {n[:-4]: round(float(v), 2) for n, v in zip(names, now) if n.endswith("_pos") and ("shoulder" in n or "elbow" in n or n.startswith("imu_"))}
    print(label, json.dumps({"control_steps":res.meta.get("control_steps"), "done":res.meta.get("done"), "reason":res.meta.get("reason"), "episode":res.meta.get("episode"), "resets_left":res.meta.get("resets_left"), "clipped":res.meta.get("clipped"), "state":arm}))

def norm_for_rad(spec, index, rad):
    lo, hi = spec["action_types"]["joint_position"]["range_rad"][index]
    return float(2 * (rad - lo) / (hi - lo) - 1)

def base_action(spec, q):
    layout = spec["action_types"]["joint_position"]["layout"]
    a = np.zeros(61, dtype=np.float32)
    for i, joint in enumerate(layout[:21]):
        a[i] = norm_for_rad(spec, i, q[joint])
    a[21:61] = -1.0
    a[21:23] = a[41:43] = 0.0
    return a

def interpolate(start, end, n):
    return np.linspace(start, end, n, dtype=np.float32)

def load_state():
    with open(STATE) as f: return json.load(f)

def save_state(d):
    with open(STATE, "w") as f: json.dump(d, f)

def run(stage):
    r = Robot(); spec = r.spec()
    if stage == "reset_reach":
        reset = r.reset(cameras=[CAM]); save_obs(reset, "start")
        obs = r.get_obs(cameras=[CAM], video="none")
        names = spec["proprio_layout"]
        q = {n[:-4]: float(v) for n,v in zip(names, obs.meta["proprio"]["now"]) if n.endswith("_pos")}
        a0 = base_action(spec, q)
        reach = a0.copy()
        for i,rad in ((11,-0.30),(14,0.80),(16,-0.30),(19,0.80)):
            reach[i] = norm_for_rad(spec,i,rad)
        rows = interpolate(a0, reach, 80)
        res = r.submit("joint_position", rows, dt=0.02, interpolate="hold", cameras=[CAM], video="none", note="reach bar with open hands")
        save_state({"episode":res.meta.get("episode"),"base":a0.tolist(),"reach":reach.tolist()})
        save_obs(res, "reach")
        report(res,spec,"REACH")
    elif stage == "grip":
        d=load_state(); a=np.array(d["reach"],dtype=np.float32); closed=a.copy()
        closed[23:41]=0.0; closed[43:61]=0.0
        res=r.submit("joint_position",interpolate(a,closed,40),dt=0.02,interpolate="hold",cameras=[CAM],video="none",note="partially close hands while holding reach pose")
        d["grip"]=closed.tolist();save_state(d);save_obs(res,"grip")
        report(res,spec,"GRIP")
    elif stage == "lift":
        d=load_state(); a=np.array(d["grip"],dtype=np.float32); target=a.copy()
        # First lift the bar toward chest height, keeping the body targets from the initial stable stance.
        for i,rad in ((11,-1.25),(14,0.25),(16,-1.25),(19,0.25)):
            target[i]=norm_for_rad(spec,i,rad)
        res=r.submit("joint_position",interpolate(a,target,100),dt=0.02,interpolate="hold",cameras=[CAM],video="none",note="raise gripped bar to chest")
        d["lift"]=target.tolist();save_state(d);save_obs(res,"lift")
        report(res,spec,"LIFT")
    elif stage == "hold":
        d=load_state(); a=np.array(d.get("lift",d["grip"]),dtype=np.float32)
